-- Generated by scripts/letters.ts from i18n/esES/letters/: edit those, not this file.
-- letterTexts[id] = { greeting, body = { paragraph, ... }, signoff (its lines), ps = { paragraph, ... } }
local _, ns = ...
ns.letterTexts = {
  [1] = { greeting = "$N:", body = { "Conocía el nombre de Edwin VanCleef mucho antes de conocer sus crímenes. En Ventormenta hay muros que levantó con sus propias manos. Me alegro de que haya terminado, y no disfruté pidiéndotelo.", "Cejade quiere llevar a su familia de vuelta a casa. Tuve que decirle que todavía no. Quería un día que pudiera marcar, y no pude darle ninguno. Aún necesitamos hombres en los caminos.", "La guardia nocturna pasó sin una sola alarma. Todavía no me fío, y les he dicho a los hombres que tampoco se fíen.", "Tienes mi agradecimiento, y el de la milicia. Quería que lo oyeras de mí." }, signoff = "Gryan Mantorrecio\nLa Milicia Popular" },
  [2] = { greeting = "$gQuerido:Querida; $N:", body = { "El monumento está terminado, según me dicen, y el gran mampostero Marmolez está satisfecho con el granito de Alterac que le trajiste. Le pregunté a nuestro rey cuánto nos costaría la guerra. Me ha respondido con granito. Al mampostero solo le pregunté si el nombre de Sully está grabado lo bastante hondo para seguir siendo legible cuando la piedra empiece a desgastarse. Quizá sea una pregunta tonta. A mí me importaba.", "Guardo su carta una y otra vez. Luego uno de los niños pregunta qué dijo su padre, y vuelvo a sacarla. El pequeño Edgar ya sabe dónde me detengo, y me espera allí antes de que pase la página.", "Hay cosas en ella que Sully nunca me dijo cuando estaba en casa. Es extraño oírlas ahora, de su puño y letra. Me habría gustado contestarle.", "Gracias por devolvérnosla. No habría soportado perder también eso." }, signoff = "Con gratitud,\nSara Balloo" },
  [3] = { greeting = "$C:", body = { "La cabeza de Ramstein está en la pared. Los perros comen podredumbre viva sin quejarse. Debajo de esa cabeza no comen. He cambiado sus cuencos de sitio.", "Cacé a Ramstein durante meses antes de que huyera a Stratholme. Tenerlo aquí ha hecho poco por el estado de la granja. No esperaba otra cosa. Quería muerta a esa criatura, y tú te encargaste de ello.", "Llegaste a mi granja siendo $gun imbécil:una imbécil;. Ahora estás entre mis campeones. Lo pongo por escrito porque de otro modo no lo creerías. Procura que no se te hinche lo que tienes por cabeza.", "Ya está. Ya lo tienes." }, signoff = "Nathanos" },
  [4] = { greeting = "$N:", body = { "Mi madre se alegró de saber que estuviste ante Cairne, joven, y lo primero que pensó fue si habías comido antes de subir. No supe decírselo, y ella opina que un jefe debería saber esas cosas.", "Todavía va ella misma al pozo por su agua. Cuando me ofrecí a llevarle el cántaro, me preguntó si un jefe no tenía nada mejor que hacer, y cuando le dije que tú ya se lo habías llevado una vez, me contestó que en lo que tardaba en decirlo, yo ya podría haber traído el agua.", "Baine me mandó noticias de ti, y se las leí a los demás junto al fuego. Los pequeños me las hicieron leer dos veces, y desde entonces hablan de los Ritos todas las noches.", "Mi madre dice que esta carta tiene demasiadas esquinas, como mis tallas. Le dije que la leerías de todos modos." }, signoff = "Camina con la Madre Tierra,\nJefe Viento de Halcón" },
  [5] = { greeting = "$gChico:Chica;:", body = { "La lente está colocada, el telescopio funciona y las botas han vuelto a las estanterías. Los clientes ya no preguntan dónde estaban. El mejor silencio que he pagado nunca.", "Escucha. Vertipeluca apuntó tu paga como flete. Le hice cambiarlo. El flete no entra solo en un campamento pirata para salir con las cajas correctas. Según mis libros, eso me deja debiéndote la diferencia. Así que Vertipeluca está arreglando los libros. No la diferencia, $gchico:chica;. Los libros.", "En Trinquete todo el mundo promete. Noventa y nueve de cada cien vuelven con una historia de por qué no pudieron. Tú volviste con mis botas. En mi oficio, eso es más raro que el oro, y de eso sé un rato." }, signoff = "Gazlowe", ps = { "P. D. Los piratas han vuelto a la playa. Les he mandado una factura." } },
  [6] = { greeting = "¡$gMi querido:Mi querida; $N!", body = { "¡Bangalash! ¡Todo el campamento sigue hablando a gritos de él a la hora de cenar! Sir Erlgadin jura que su pantera era la presa más difícil, y Ajeck no quiere ni oír hablar de ello. He tenido que mover la tetera dos veces para salvarla de sus demostraciones.", "¡Erlgadin, Ajeck y yo tenemos mucho que decir sobre cierto tigre que abatiste! Llevaba muchísimo tiempo con ese diablo blanco en el punto de mira, ¡y me he ganado el derecho a decir una o dos cosas al respecto!", "Barnil leyó mi relato de la cacería y me preguntó dónde salías tú. ¡Buena pregunta! Me temo que me dejé llevar tanto por mis propias cacerías que me olvidé de ti por completo. Bueno, ya te he puesto en el lugar que te corresponde.", "¡Magnífico trabajo! ¡Levanto mi copa por ti, salud! ¡Salud!" }, signoff = "Hemet Decautela" },
  [7] = { greeting = "¡Saludos desde la cueva, $N!", body = { "Sigo justo donde me encontraste. Ya me siento mucho mejor, te lo prometo. Bueno, casi. Todavía hay un montón de arañas Tejemadera entre el resto de Cañada Umbría y yo, y un elfo sensato espera a que parezcan ocupadas.", "Dirania me manda decir que ya puedo volver a casa andando. También me recuerda, cada vez, que siempre me advirtió sobre esas arañas. Bueno, es verdad.", "Antes iba a verla todos los días a la misma hora. Ahora sabe exactamente dónde estoy a cada hora, y creo que lo prefiere.", "Siempre me estoy metiendo en problemas, y siempre hay alguien que me saca de ellos. Normalmente es Dirania. Esta vez fuiste tú, con cinco minutos para lograrlo. Gracias." }, signoff = "Tu amigo,\nIverron" },
  [8] = { greeting = "$N:", body = { "La fruta que encontraste es lo más interesante de mi campamento. La guardo envuelta, bien lejos de la tierra, hasta entender qué pasó entre ambas. ¿La culpa fue de la fruta o de la tierra de Teldrassil? Preferiría que fuera de la fruta.", "Las semillas de Brezomadera están en la tierra especial, con la tierra rara que trajiste de Dolanaar, y voy a verlas más a menudo de lo que serviría de algo. Me dicen que una semilla vigilada nunca brota. No he podido comprobar si es cierto o falso.", "Lo que sé: la planta que dio la fruta es una extraña aquí. Quizá su semilla llegó desde muy lejos. Lo que no sé: casi todo lo demás. Es una posición maravillosa.", "Tienes buen ojo, $N. Gracias por prestármelo." }, signoff = "Respetuosamente,\nDenalan" },
  [9] = { greeting = "¡$N!", body = { "¡¡Lo hice!! Me bebí hasta la última gota y pasé justo por delante de la casa, y nadie vio nada. ¡Nada de nada! Oía mis propios pasos y estaba segura de que todo el viñedo los oía también.", "Tommy Joe estaba en el río, justo donde siempre está. Claro que él tampoco podía verme, así que tuve que decir su nombre, y dio tal salto que creí que se caía al agua. Luego se rio, y luego yo, y hablamos hasta que volví a verme las manos. Volví a casa corriendo todo el camino.", "Sé que estuvo mal engañar a mi familia. ¡Lo volvería a hacer sin pensarlo!", "¡Ni siquiera puedo darles las gracias al señor Mortero ni a la Abuela Pedregosa, porque se supone que no conozco a ninguno de los dos!", "Tú llevaste mi carta a Tommy Joe. Esta es para ti." }, signoff = "Con todo mi cariño (¡pero no de ese!),\nM." },
  [10] = { greeting = "$gQuerido:Querida; $N:", body = { "El collar ha vuelto a su sitio. Duermo con él puesto. Que lo intenten los kóbolds.", "Ese Billy Maclure le cuenta a cualquiera que se quede quieto que mi pastel fue el mejor que ha comido nunca. Pues claro que lo fue. Esa no es la cuestión. La cuestión es que se llevó mi collar y encima le dieron pastel por las molestias, y ahora medio bosque conoce mi pastel mejor que mi nombre.", "Te di los guantes de mi marido porque no le hacían ningún bien a nadie colgados del gancho junto a la puerta. Él siempre decía que daban suerte, y luego se fue a su última campaña sin ellos. He mirado ese gancho mucho tiempo. Mejor que salgan por la puerta con alguien.", "Gracias, cariño. Le has calentado el corazón a esta vieja viuda, aunque lo negaré delante de cualquier Maclure que pregunte." }, signoff = "Tía Bernice", ps = { "P. D. No le puse nada al pastel de Billy. Lo pensé." } },
  [11] = { greeting = "¡Salud, $N!", body = { "Mi hermano dice que la Cerveza negra Brillante le pone brillo en los ojos y que ve en la oscuridad. El montaraz Kadrell me escribió desde Thelsamar que aligera las piernas y que se siente capaz de volar. Un cervecero podría vivir de palabras así, y casi lo hago. Gracias por llevársela, $gmuchacho:muchacha;.", "El problema es este: no es perfecta. Una cerveza negra que hace sentir a un enano que puede volar es una buena cerveza negra. Una cerveza negra perfecta le deja las botas en el suelo y hace que se alegre de ello. La cardaluz es la nota justa. Lo que falla es la malta de debajo, demasiado dulce o no lo bastante oscura, y tengo tres tandas pequeñas en marcha para averiguarlo.", "Esto de hacer cerveza lo llevo en la sangre, y la sangre es paciente. Lo conseguiré." }, signoff = "Rejold Cebadiz" },
  [12] = { greeting = "$N:", body = { "Madera: poca. Peones: dormidos. Dos debajo del mismo árbol, uno en el montón de leña y uno de pie. No sabía que podían hacer eso.", "A ti sí te recuerdan. Corrió la voz de que andabas $gsuelto:suelta; por el valle con mi porra. Ahora, cuando uno oye pasos, ya está de pie dando hachazos antes de abrir los ojos. No dura. Mejor que nada.", "Preguntan si vas a volver. Les digo que sí. No les digo cuándo.", "Buen trabajo. Gracias por la ayuda." }, signoff = "Thazz'ril\nSupervisor" },
  [13] = { greeting = "$N:", body = { "La noche que me trajiste la cabeza no dormí. Me senté junto al agua y escuché. No llegó ningún tambor desde las islas. Detrás de mí dormía el poblado, entero, como antes. Quería oír eso.", "Desde la orilla se ven las Islas del Eco. Todavía sé qué playa era la mía. No son nuestras. Las miro de todos modos.", "Algunos de los que combatiste eran de los Lanza Negra, antes del maleficio. No los llores. Eso nos corresponde a nosotros, y ya lo hemos hecho." }, signoff = "Gadrin" },
  [14] = { greeting = "Joven $N:", body = { "Las bestias vuelven a beber en el Pozo Pezuña Invernal, con tantas ganas como el día en que fue purificado. He visto a los zancudos de llanura inclinarse sobre él, y a los lobos bajar después, y cada vez he pensado que beben un agua que los suyos ayudaron a purificar. Ellos no lo saben, pero la tierra sí, y yo también.", "Cada tótem pidió algo a las bestias de Mulgore, hasta los colmillos de los alfas, y mi espíritu aún les guarda duelo, y está orgulloso. No eligieron dar, y fuiste tú quien llevó su ofrenda hasta los pozos.", "Cuando el viento baja del norte, oigo a los espíritus hablar de ti." }, signoff = "Que los espíritus te guíen,\nMull Tronacuerno" },
  [15] = { greeting = "$N:", body = { "Te escribo para acusar recibo del informe de la guardia de la Muerte Linnea, entregado de tu mano y sin demora. En Rémol, la puntualidad es lo bastante rara como para merecer mención.", "El informe decía lo que ella te contó. El Baluarte contiene a la mayor parte de la Plaga, y algunos se cuelan. Lo he archivado con los demás que dicen lo mismo.", "Las tumbas junto a la Granja de Garren no son seguras, pero los muertos que hay en ellas siguen muertos, que era el objetivo. Se libraron de lo que nos hicieron a nosotros. Descubro que tengo un interés personal en que siga siendo así, y tu trabajo entre los Putrepellejo lo ha favorecido. Los boticarios tienen el icor. No me han dicho nada, lo que en mi experiencia significa que están satisfechos.", "El rey Exánime y sus esbirros no cesan en sus ataques. Nunca volverá a cogernos." }, signoff = "Con mi agradecimiento oficial,\nMagistrado Sevren" },
  [16] = { greeting = "$N:", body = { "¿Todavía lo sientes, el zumbido junto a las piedras erguidas? ¿Sí? Bien. Entonces ha funcionado, y volverás a sentirlo en muchos lugares.", "Las líneas ley vivían antes en los libros viejos. Ahora atraviesan la hierba para salir a nuestro encuentro. Don o advertencia, es conocimiento, y pienso tenerlo todo antes de que otro decida lo que se me permite saber.", "Rorian te entregó tu reliquia y te dijo que los vientos de tu hogar te acompañarán allá donde vayas. Rorian lo cree, y es algo bonito de creer. Yo prefiero lo que se puede medir.", "Son tiempos difíciles para los shen'dorei, y sé qué quiero primero: conocimiento, y después poder." }, signoff = "Descubre lo desconocido,\nFalorne Trombaviento" },
  [17] = { greeting = "$N:", body = { "Tu Visión cielonata es como un músculo. Debes ejercitarla, porque un músculo que se deja en paz se ablanda. Úsala en el camino, en la posada, bajo la lluvia. La mayoría de los días no verás nada que merezca la pena. Úsala de todos modos.", "Yo mantengo la mía abierta un rato cada noche, aquí en la aldea, antes de dormir. Algunas noches capto una o dos palabras, débiles como una voz al otro lado de una pared. Otras noches, nada. He aprendido a no guardarles rencor a las noches calladas. También forman parte de la práctica.", "Apunto lo que capto, aunque no tenga sentido. Sobre todo entonces. Los espíritus no se repiten para nuestra comodidad.", "Vamos a necesitar a todos los que sepan escuchar." }, signoff = "Paciencia,\nVentaari Deseo Claro" },
  [18] = { greeting = "$N:", body = { "Envié a Belathaan al Santuario de Akir porque la lógica lo dictaba. Hablar cuesta menos que sangrar, y la paz menos que la guerra. Cada paso de ese razonamiento era sólido. El culto respondió con una caja. He repasado mis argumentos muchas veces desde entonces, buscando el error, y solo lo encuentro en mi juicio sobre aquellos a quienes lo envié.", "Los Formavientos tenían razón. Escribirlo es peor que decirlo.", "Los talismanes que me trajiste están guardados bajo llave. Los miro menos que antes. No he olvidado quién me los trajo.", "El culto confundió nuestra prudencia con debilidad. También eso fue un juicio, y el suyo es el peor." }, signoff = "Elaadrin Vendaval del Atardecer\nMagister supremo de la Orden Eminente" },
  [19] = { greeting = "$N:", body = { "Te debo una respuesta mejor que la que te di cuando me trajiste los talismanes. «Un día difícil» no lo era.", "Los Formavientos decimos sangre por sangre. Lo he dicho toda mi vida, y lo decía en serio cuando te envié al norte. Todavía lo digo en serio. Los novicios que encontramos en las Tierras Altas eran de los nuestros, y alguien responderá por cada uno de ellos.", "Pero también te había enviado tras Belathaan, para asustarlo, y él nunca volvió de ese camino. Te dije que no era culpa tuya. Era cierto. No dije de quién era, porque aún no lo había decidido. De Elaadrin, por enviarlo. Del culto, por matarlo. Mía, por querer que tuviera miedo. Su madre era una de los nuestros.", "No perdonamos y no olvidamos. A él tampoco lo olvidaré." }, signoff = "Ayessa Cantoalba\nSuma vidente del cielo de los Formavientos" },
  [20] = { greeting = "$N:", body = { "¡La Presa sigue en pie! Bajo a la base cada mañana y cada tarde para mirarla, y sigue en pie, y cada vez doy gracias a las estrellas. Ay, cielos, espero que nunca sepas lo que habría hecho esa pólvora mojada. Lo calculé dos veces sobre el papel, ¡¡y luego dejé de calcularlo!!", "El destacamento de seguridad sigue en el frente de la Alianza, y mi mejor inspector con él. Así que quedamos yo, los montaraces que me puedan prestar y el agua. Ahora golpeo cada barril por el que paso. Todos y cada uno.", "Viniste cuando nadie más vino, y removiste ese barril como si fuera sopa. No sé si fue valor o ignorancia, ¡y te lo agradezco igual!", "La Presa está a salvo, al menos por ahora, y también todos los que viven por debajo de ella." }, signoff = "Tuyo, con cierta prisa,\nHinderweir VII\nIngeniero Jefe de la Presa de las Tres Cabezas" },
  [21] = { greeting = "$N:", body = { "Por una vez, una carta mía que no tienes que llevar a ninguna parte.", "He leído las tres respuestas que me trajiste más veces de las que un magistrado debería leer nada. Ventormenta enviará refuerzos cuando el rey dé la orden. Los Páramos de Poniente no tienen hombres de sobra, y sí sus propios muertos que enterrar. Villa Oscura no puede enviar a su Guardia Nocturna más allá del linde de su propio bosque. Cada respuesta es razonable. Juntas no tienen ningún sentido.", "Villa del Lago resiste, por ahora. Hay traición en algún lugar de todo esto, y pienso averiguar de quién. Bah. No debería pensar en voz alta, ni siquiera sobre el papel.", "Recorriste un largo camino por un pueblo que no te debía nada, y cada vez volviste con la verdad, aunque la verdad fuera que no. Gracias." }, signoff = "Magistrado Salomón\nVilla del Lago" },
  [22] = { greeting = "$N:", body = { "Hollee me dice que fuiste tú quien me sacó de la excavación, y que yo no estaba, como creía entonces, dando un simple paseo. Dice que había gólems. Yo recuerdo una capa de sedimento muy interesante.", "También me dice que mi fósil ha estado en Darnassus y luego en Puerto de Menethil, lo que es más de lo que yo he viajado en años, y que ahora lo tiene un tal Gargavino, junto con una piedra suya. ¡Espléndido! Espero que escriba. Que me escriba a mí, quiero decir, y no a Hollee, aunque Hollee parece recibirlo todo.", "He estado buscando mi pincel de piedra. Lo menciono solo porque lo he estado buscando todo el tiempo que he tardado en escribir esto, y me pareció de mala educación no decirlo." }, signoff = "Con agradecimiento y, creo, disculpas,\nProspector Tripirrem" },
  [23] = { greeting = "$N:", body = { "¡El NG-5 llegó en perfecto estado, es decir, no te estalló encima por el camino, y eso lo cuento como un éxito para todos los implicados!", "Lomac es el mejor químico que me ha gritado jamás. Si te dijo que me saludaras, lo decía en serio. Si te dijo otra cosa, también lo decía en serio, solo que menos.", "Todo está en su sitio. No te voy a contar el plan, en parte porque un plan contado es un plan estropeado, y en parte porque cambia cada vez que lo miro. Hay carros. Hay dinamita, que no es tan peligrosa como piensa todo el mundo. Hay magia, combinaciones y mecanismos trabajando juntos, que es justo de lo que va la Asamblea y, francamente, de lo que voy yo.", "Los elfos de la noche todavía me miran como si fuera a estallar. Con razón. Demostrarles que un gnomo puede ayudar a salvar sus bosques es mi objetivo... no, ¡mi DEBER!" }, signoff = "Gaxim Silvóxido\nAsamblea Iluminada de Arcanología, Alquimia e Ingeniería" },
  [24] = { greeting = "$N:", body = { "Ha llegado el momento del duelo, como dije que llegaría, y no respeta ninguna hora que yo elegiría. Escribí a la familia de Teronis. Fue la carta más corta que he escrito nunca, y me llevó toda la noche.", "Lo encontraste, y encontraste lo que buscaba cuando murió. Fue más de lo que me atrevía a esperar, y no es suficiente.", "Los fúrbolgs no siempre fueron nuestros enemigos. Cuando era joven, nunca tensé el arco contra uno. Ahora te he enviado por el camino de sus campamentos y lo he llamado defensa, y lo era. Solo quiero que quede escrito en algún lugar que recuerdo los tiempos más tranquilos." }, signoff = "Que Elune te guarde,\nRaene Correlobo" },
  [25] = { greeting = "$N:", body = { "Se lo he contado a la suma sacerdotisa. Lo que pasó entre nosotras me lo guardo. Solo diré que tomé el camino largo de vuelta al barracón.", "El arcón de Velinde sigue en el barracón. No soy capaz de mandar que lo vacíen. Las Centinelas creían que tenía sus propias razones para marcharse y que volvería cuando quisiera. Yo también lo creía, y así te lo dije. Habría preferido equivocarme en casi cualquier otra cosa.", "Me inquieta que la Guadaña de Elune haya escapado de las manos de sus siervas.", "La seguiste por medio mundo fiándote de un libro que se escribe solo. Pocos lo habrían hecho. Te debo mi agradecimiento, y no poco." }, signoff = "Thyn'tel Tejespada" },
  [26] = { greeting = "$C:", body = { "Perdona mi mal humor cuando viniste a verme. Estaba furioso como un kodo con dolor de muelas, y tú no habías hecho nada para merecerlo. La culpa fue mía. Envié viajeros bajo la ciudad sin pensar en quién más podría seguirlos, y dos amigos pagaron por mi descuido. Algún enviado de Thrall, quienquiera que fuese. Daría mucho por saber sus nombres.", "Estoy poniendo orden ahí abajo en lo que puedo. Nuestros amigos de Los Baldíos y del bosque han empezado su propio trabajo.", "Llegaste en el momento justo, con la insignia justa. No lo olvido. En una ciudad donde tan pocos son lo que parecen, es un consuelo conocer a alguien que sí lo es." }, signoff = "Un amigo en el Circo" },
  [27] = { greeting = "$N:", body = { "He sacado lo que he podido de los grilletes de Piroleña que me trajiste. No fue suficiente. Ya lo sospechaba, y creo que lo dije. Una muestra limitada es una muestra limitada.", "Aun así, ahora entiendo el remedio, o casi todo, y cuanto más lo entiendo, peor opinión tengo del hombre que lanzó el hechizo. El Kirin Tor le abrió sus salones. He dejado de preguntarme cómo.", "En Piroleña siguen siendo hombres y mujeres de día, y otra cosa cuando se pone el sol. Arugal le hizo eso a un pueblo entero con un hechizo que cualquier aprendiz se avergonzaría de firmar. Eso es lo que más me cuesta perdonar. No la maldición. La chapuza.", "Llevará más tiempo del que pensaba. Todo lo que tiene que ver con Arugal lleva más tiempo del que pienso. Quizá sea su único talento.", "Mis respetos, $N." }, signoff = "Dalar Tejalba\nEl Sepulcro" },
  [28] = { greeting = "$N:", body = { "Antes de que partieras hacia la Isla de Fenris, escribí dos informes para Entrañas. Uno decía que Thule Corvozarpa había muerto. El otro, que te había enviado tras él y que no habías vuelto. Un comandante debe estar preparado para ambos. Quemé el segundo el día que volviste con su cabeza.", "Renferrel me dice que las energías liberadas cuando cayó Thule se sintieron hasta en el Sepulcro. Tiene razón. Yo mismo las sentí, y supe lo que habías hecho antes de que nadie me lo dijera.", "La Plaga no ha terminado en el Bosque de Argénteos. Los Putrepellejo siguen ocupando la isla, y no la abandonarán por un mago muerto. Pero han perdido terreno, y lo han perdido ante $guno:una; de los nuestros.", "Tu valor para nosotros crece." }, signoff = "Sumo Ejecutor Hadrec\nEl Sepulcro" },
  [29] = { greeting = "$N:", body = { "No se me dan bien las cartas. Ella era la de las palabras.", "Contuvo sola a tres jabaespines. Cuando llegaron más, me llevé a algunos lejos y me dije que esa era la parte valiente. Ahora ya no me lo digo.", "El druida que me encontró en el camino me dijo que descansara. Descansé. Luego volví al campamento donde nos separaron y maté a todos los jabaespines que encontré allí. Eso tampoco ayudó.", "La encontraste cuando yo no pude. No sé qué viste allí, y no te lo pregunto.", "Gracias, $C." }, signoff = "Mankrik" },
  [30] = { greeting = "$N:", body = { "He dormido toda la noche. Entera, desde que oscureció hasta la primera luz sobre el Alto, y me he despertado con las manos abiertas. Había olvidado que el sueño podía ser tan sencillo.", "Cuando el anciano dejó el sueño, yo me quedé, porque alguien tenía que verles la cara. Se la vi. Luego no pude dejar de verla. Cuatro caras, cada noche, volviéndose hacia mí como si me conocieran. Me despertaba con los puños cerrados y los dientes doloridos. Ya no vienen.", "Antaño fueron druidas. Su orden quería sanar Los Baldíos. Pienso en ello más de lo que querría. Sería más fácil odiarlos si siempre hubieran sido lo que llegaron a ser.", "La tierra sigue soñando, y mal. Eso nunca fue obra de una sola noche. Pero mis sueños vuelven a ser míos, y fuiste tú quien los recuperó." }, signoff = "Nara Bravacrín" },
  [31] = { greeting = "$N:", body = { "Los búnkeres resistieron. Krom'zar vino desde Desolace en busca de venganza, y lo que encontró fuiste tú.", "Barak, Verog, Hezrul y luego Krom'zar. He luchado contra centauros casi toda mi vida, y nunca había visto caer a cuatro de sus líderes a manos de una sola persona. Un centauro con cabeza para mandar es raro, y esos son los peligrosos. Tú te encargaste de los peligrosos.", "Los Kolkar volverán. Siempre lo han hecho. Cuando vuelvan, vendrán contándose unos a otros lo que hiciste, y espero que lo cuenten mal.", "Ve con la cabeza bien alta, $N." }, signoff = "Regthar Portamorta" },
  [32] = { greeting = "$R:", body = { "Quebrantadientes escribe. <gruñe> Manos no hechas para plumas. Lee de todos modos.", "Quebrantadientes te vio correr, desde la jaula. Corriste con las astacebras. El viento tenía celos, como dijo Quebrantadientes. <gruñe> El espíritu de Agamaggan todavía responde a Quebrantadientes, con barrotes y todo. Ninguna jaula detiene eso. Recuérdalo.", "Erizapúas más débiles ahora, gracias a ti y a Quebrantadientes. Y los Crines de Acero siguen sin venir. Quebrantadientes contó los días. Luego Quebrantadientes dejó de contar. <gruñe>", "El contacto con los fragmentos. Mucho tiempo desde que Quebrantadientes tuvo uno. No sabes lo que se siente cuando te apartan de tu poder. Quebrantadientes espera que nunca lo sepas.", "Quebrantadientes no es tonto. Quebrantadientes está agradecido. Las dos cosas. <gruñe>" }, signoff = "Quebrantadientes\nCampamento Taurajo" },
  [33] = { greeting = "$N:", body = { "Los goblins siguen talando el Risco. Cuando sopla el viento del oeste, huelo su humo desde aquí, en la frontera. Dos máquinas rotas no les van a enseñar nada, y nunca pensé que lo harían.", "Pero casi todo el llanto ha cesado. No la pena, el llanto. Los espíritus siguen heridos, y tienen todo el derecho a estarlo. Ya no están ciegos de dolor.", "Puede que los ancianos todavía tengan que venir a calmar lo que queda. Ya te lo dije. Te lo repito para que nunca confundas una victoria con un bosque.", "Los espíritus me dieron las marcas de esas máquinas. Tú les hablaste a las máquinas en el único idioma que entienden los goblins. Me parece un reparto justo del trabajo." }, signoff = "Con rabia y con esperanza,\nSeereth Rompepedras" },
  [34] = { greeting = "¡$gAfortunado:Afortunada; $N!", body = { "¡Treinta! ¡Treinta calaveras preciosas, y todas y cada una de ellas bellísimas! Las cuento en cada cambio de guardia, por si alguna ha rodado a alguna parte. Ninguna lo ha hecho. Se portan muy bien.", "Las tengo donde nadie las ve, donde Darthalia no puede verlas. Ella opina que un guardia de la Muerte de servicio debería estar haciendo guardia. Y la hago. Las guardo con muchísimo cuidado.", "En este puesto nunca pasa nada. Mientras tú estabas por Trabalomas pasándolo en grande, yo tenía tanta envidia que podría haberme caído a pedazos, lo que a mi edad es un riesgo real.", "Espero que te detengas en la puerta cuando pases, aunque solo sea para que pueda volver a darte las gracias." }, signoff = "Tu fiel guardia de la Muerte,\nSamsa\nMolino Tarren" },
  [35] = { greeting = "$N:", body = { "El puerto está abierto. Barcos que entran, barcos que salen, y ni una tripulación vigilando las colinas mientras amarra. Eso es obra tuya.", "Te diré lo que le dije a Valcorno. Una máquina de asedio es una cosa paciente. Se queda en las colinas y espera a que uno se ponga cómodo. Nek'rosh tenía las suyas esperándonos, y tú les acercaste un poco de yesca a todas y cada una. Vi el humo desde la muralla del torreón y no dije ni una palabra en un buen rato.", "Los Faucedraco no han terminado. Se lamerán las heridas en esas colinas mucho tiempo, y yo estoy vigilando. Pero lo harán mirando un puerto que sigue en pie.", "Dije que eras $gun:una; $R de méritos innegables. Lo repetiría delante de cualquiera." }, signoff = "Capitán Puñorrecio\nPuerto de Menethil" },
  [36] = { greeting = "$N:", body = { "Cada mañana camino hasta el Ayuntamiento pasando junto a muros que los canteros levantaron después de la guerra. Edwin colocó algunas de esas piedras él mismo. Antes se las señalaba a los visitantes. He dejado de hacerlo.", "Me trajiste su carta nunca enviada, y luego seguiste su rastro por Las Mazmorras y más allá. He oído que encontraron muerto a lord Lescovar. No he preguntado cómo, y no lo haré. Te estoy agradecido. Lo digo primero, porque lo demás es más difícil de decir.", "Cuando los nobles se negaron a pagarnos, a algunos nos ofrecieron puestos. Yo acepté el mío. Edwin rechazó el suyo, por lealtad a los demás, y juró venganza. Te dije que no le importaba a quién hacía daño, y que no estaba seguro de poder culparlo. No he cambiado de opinión sobre ninguna de las dos cosas.", "La ciudad sigue en pie, y yo guardo sus planos. Algunas mañanas eso me parece una respuesta para él, y otras, el puesto que él no quiso aceptar." }, signoff = "Baros Alexston\nArquitecto urbano" },
  [37] = { greeting = "$N:", body = { "Volví a la granja. Es la primera vez desde aquella noche. El granero sigue en pie, y también el viejo tocón donde estaba enterrado el libro. Me quedé allí un buen rato. Luego regresé a mi campamento, y dormí.", "Morbent Vil ha sido derrotado. Los jinetes oscuros no, y no voy a fingir lo contrario. Pero se ha cumplido una pequeña parte de lo que había dejado de esperar, por tu mano y por esa espada de Ventormenta.", "Ahora sé quién es Altero. Vio morir a mi familia sin poder hacer nada, y lo escribió todo porque no podía cargar con ello solo. Descubro que no puedo odiar a un hombre por eso. Intento no hacerlo.", "Quizás un día, el destino vuelva a traerte a mí. Lo digo como lo dije entonces." }, signoff = "Sven Yorgen" },
  [38] = { greeting = "$N:", body = { "He vuelto a echarle las cartas a Alyssa. La Muerte no salió. Lo que salió fue una carta que no veía desde hacía mucho, una carta corriente, sin ninguna importancia. Significa un día normal. Me quedé sentada mirándola hasta que se me enfrió el té.", "Seguiste un nombre salido de mi trance hasta el registro, hasta Arroyo de la Luna, Villadorada y Ventormenta, y de regreso, y cada puerta a la que llamabas se abría a algo más antiguo y peor. Yo te mandé por ese camino. Lamento parte de lo que encontraste al final.", "El bosque sigue oscuro. Las cartas lo dicen, y rara vez se equivocan con el Bosque del Ocaso. Pero hay una sombra menos sobre esta casa.", "Alyssa no sabe lo cerca que estuvo, y pienso mantenerlo así." }, signoff = "Lady Eva" },
  [39] = { greeting = "$N:", body = { "Te escribo desde Punta de Nijel, con el equipaje preparado para Darnassus. Vahlarriel dice que puedo irme cuando esté lista. No dejo de encontrar pequeñas razones para no estarlo todavía.", "Te di las gracias por la muerte de mi hermano. He pensado en eso más que en nada de lo que me hicieron los orcos. Lo decía en serio, y no lo decía en serio, y las dos cosas siguen siendo ciertas. Si no hubiera sido tu mano, habría sido la de alguno de los míos. Es un consuelo frío, pero es el que tengo.", "Mi padre preguntará qué buscaba Tyranis aquí. Le diré la verdad: conocimiento, más del que le convenía, más del que nuestro pueblo permite. No le diré cómo terminó.", "Me sacaste de esa fortaleza y me dejaste salir por mi propio pie. Eso es lo que mejor recordaré." }, signoff = "Dalinda Malem" },
  [40] = { greeting = "$N:", body = { "Quae dice que me preocupo demasiado. Quae tiene razón, y eso nunca me ha detenido. Así que ahora que sé que mis dos alborotadores están vivos, he encontrado a alguien nuevo por quien preocuparme. A ti.", "He estado leyendo lo que Kin sacó de esa granja. De noche, que es una mala costumbre, porque no es la clase de lectura que ayuda a dormir a un hombre. Sea lo que sea lo que Jorell está tramando ahí fuera, me apuesto las botas a que tiene algo que ver con Stanley.", "Mi primo sigue sin querer hablar de ese perro. No se lo reprocho.", "En fin. Come algo caliente, ponte de espaldas a la pared y bebe menos que Kin." }, signoff = "Phin Odelic\nCostasur" },
  [41] = { greeting = "$gEstimado cliente:Estimada clienta;:", body = { "En relación con tu reciente consulta. La rueda que buscabas salió de Menethil en barco mucho antes de que empezaras a hacer preguntas, como ya descubriste allí. Nuestro amigo del puerto te manda saludos y dice que echa de menos la emoción, cosa que me pidió que no repitiera, así que haré como si no la hubiera escrito.", "El resto del pedido está ahora con nuestros amigos de Theramore, y son gente cuidadosa. Que la rueda vuelva a aparecer ya no está en mis manos.", "Diré una cosa con claridad. Hiciste más trabajo de calle del que te pagué, y nadie más que tú ha hecho llegar una palabra de ello a mi tienda. Me he dado cuenta. Me doy cuenta de casi todo." }, signoff = "Agradecido por tu confianza,\nElling Trias\nMaestro quesero" },
  [42] = { greeting = "$N:", body = { "Envié a Caldwell a Punta Perdida, como dije que haría. El pantano no es tan grande ni tan intrincado como para que un hombre se esconda en él para siempre, aunque Reethe parece decidido a ponerlo a prueba.", "Jim sigue sonriendo a todo el mundo. Me paro a hablar con él cuando puedo. Habla de la posada como si siguiera en pie junto al camino, y lo dejo.", "Nunca es buena noticia que me traigan la placa de un guardia. La de Reethe era de la peor clase: un hombre tan leal al viejo almirante que renegó de su juramento, y luego tan temerario que ni los desertores con los que huyó lo soportaron. Nos llaman traidores a nosotros. Les concedo la ironía.", "Balos Jacken te pidió que olvidaras que te habías topado con ellos. Por favor, no lo hagas." }, signoff = "Capitán Garran Vimes\nTheramore" },
  [43] = { greeting = "$N:", body = { "Soy el magistrado de un pueblo de pescadores. Resuelvo peleas por redes y mojones, y de vez en cuando la de algún borracho que ha confundido la puerta de otro con la suya. No estaba hecho para nombres como el Despertar de Argus.", "Dibbs ha revisado todos los libros que tiene buscándolo, y no ha encontrado nada.", "Te ocupaste de los magos de las Tierras Altas, y el Sindicato ha salido perdiendo. Ojalá eso fuera el final. Pero aquel a quien servía Nagaz sigue ahí fuera, más lejos que Alterac, y yo soy un hombre al que le gusta saber dónde viven sus preocupaciones.", "Así que por las tardes miro al norte, donde antes miraba el agua. Gracias por traerme lo que no quería saber. Mejor yo que nadie." }, signoff = "Magistrado Henry Maleb\nCostasur" },
  [44] = { greeting = "$N:", body = { "La tablilla está con los magos del rey, bajo más cerraduras de las que tengo llaves. Lo que aprendan de ella les corresponde decirlo a ellos. Lo que yo puedo decir es que nunca llegó a manos de los Forjatiniebla, y que fue el sueño de Dedomaza mucho antes de ser asunto de nadie.", "Karnik me cuenta que ha hablado con el espíritu de Dedomaza. Soy consejero, no sacerdote, y no sé qué pensar de eso. Pero dice que Dedomaza está en paz, y he decidido creerle.", "Ay. Un enano que se pasó la vida buscando de dónde viene nuestro pueblo, y que la acabó asegurándose de que las manos equivocadas no lo encontraran antes. Yo no lo habría hecho ni la mitad de bien, ni en su lugar ni en el tuyo.", "Esa es una vida que merece la carta de un consejero, y tú eres la razón de que no se desperdiciara." }, signoff = "Consejero Belgrum\nForjaz" },
  [45] = { greeting = "$N:", body = { "Le arrebataste el Ojo de la mente a Mai'Zoth, y lo primero que decidí fue no mirar dentro. Un hombre que se propone averiguar si algo puede usarse para el bien no debería empezar dejando que ese algo lo use a él.", "Está envuelto y guardado. Rezo a su lado, y leo lo que otros han escrito sobre cosas así. Si hay algo bueno en él, lo encontraré. Si no, será destruido, y no lo lamentaré.", "Pienso a menudo en el coronel Kurzen tal como era, un hombre grande y noble. Las leyendas, los fetiches, todo apuntaba a una verdad: lo que lo quebró vino de fuera. Es un consuelo, y también una advertencia. Podría haberle pasado a cualquiera de nosotros.", "¡Que las fuerzas nunca te fallen, $N!" }, signoff = "Hermano Nimetz\nAsentamiento Rebelde" },
  [46] = { greeting = "$N:", body = { "¿Qué tal está el pequeñín? Me lo he estado preguntando, y un viejo domador de bestias tiene derecho a preguntárselo.", "Unas cuantas cosas que vale la pena repetir, ya que el huevo se abrió antes de tiempo. Los duendes dardo comen carne y verdura, las dos cosas, así que no dejes que nadie te diga lo contrario. Flancos crudos, ojo, y en cantidad.", "Los críos, ¿eh? Un momento vas corriendo con un huevo por medio mundo con una hora de margen, y al siguiente eres $gpapá:mamá;. Más o menos.", "Ja, ja. Cuídate, y cuida también al pequeñín, si te lo quedaste." }, signoff = "Agnar Domabestias\nPico Nidal" },
  [47] = { greeting = "$N:", body = { "Picoafilado ha volado con toda la escuadra por primera vez. Iba demasiado abierto por la izquierda y demasiado orgulloso de sí mismo, y su madre tuvo que devolverlo a la formación dos veces. Fue lo más bonito que he visto desde este pico en años.", "Mandé aviso a Thadius al Castillo de Nethergarde, por su parte en ello. Hace mucho que se fue tras un conocimiento más oscuro, y aquí hay quien todavía no quiere pronunciar su nombre. Pero fue su visión la que encontró al pequeño, y en el fondo sigue siendo un Martillo Salvaje.", "Los jinetes están componiendo una canción. No es una buena canción. Las canciones de los Martillo Salvaje nunca lo son, el primer año. La cantarán de todos modos durante mucho, mucho tiempo, y tu nombre figura en cada estrofa que llevan compuesta." }, signoff = "Maestro de grifos Garracha\nPico Nidal" },
  [48] = { greeting = "$N:", body = { "Te escribe Emma Piedra Mácula. He vuelto a firmar así, después de tantos años. Es como un abrigo que me dejé en casa de alguien.", "He revisado todo lo que envió Janice. Cartas viejas. Una receta de mi madre que había olvidado. Las escrituras de la granja, nada menos, como si yo fuera a volver allí. Siempre hacía el equipaje como quien se muda para siempre.", "Te llamé saqueatumbas. Diré que lo siento una vez, sin rodeos, y luego no volveremos a hablar de ello. Lo siento.", "Si ese amuleto hizo lo que yo esperaba, entonces ella descansa, y ya no espera ninguna entrega. Si no, no me lo digas. Prefiero pensar que sí." }, signoff = "Emma Piedra Mácula" },
  [49] = { greeting = "$N:", body = { "No entiendo por qué el Jefe de Guerra quiere una cosa tan pequeña. Una cadenita, una piedrecita. He visto a guerreros morir por menos, y por más, y no sé cuál de las dos es esta. La envié a Orgrimmar de todos modos, cosida en la bolsa de un jinete. Lo sigo a él. Eso me ha bastado hasta ahora, y me basta ahora.", "Gol'dir te dijo que seguiría su propio camino en cuanto arreglara sus asuntos, y le creo. Es un orco de palabra.", "En cuanto a la muchacha, espero que se haya ido a algún lugar lejos de esa mansión. La retenían allí contra su voluntad, como a nuestros guerreros los retenían en Durnholde. Me alegra que nadie le hiciera daño." }, signoff = "Krusk\nMolino Tarren" },
  [50] = { greeting = "$N:", body = { "Otro joven se quedó en las tablas sobre el cañón y no pudo dar el salto. No lo empujé. La fe que se empuja no es fe.", "Le dije al joven lo que te dije a ti: el espíritu, el cuerpo, la mente. Te pusimos a prueba en los tres, y ninguno de nosotros te lo puso fácil. Parqual pensaba que eras un fraude. Braug pensaba que podrías olvidar tus lecturas. Yo siempre pensé que saltarías.", "Viniste a mi casa, y al volver ya no eras igual. Habías hallado el equilibrio, y eso es más raro que la fuerza.", "Mantén el equilibrio." }, signoff = "Dorn" },
  [51] = { greeting = "$N:", body = { "Que un ogro torpe se mantuviera tanto tiempo fuera del alcance de la Dama Oscura con nada más que una corona me inquieta más que si hubiera sido de oro. El gran poder debería tener al menos la decencia de aparentarlo.", "La corona ha sido entregada. Se la llevé yo misma a la Dama Oscura, y confieso que la sostenía un poco apartada de mí, como quien lleva algo que podría morder.", "Ya sabe de tu papel en todo esto. Me encargué de ello, como dije que haría. Tu nombre se ha pronunciado en el Barrio Real, y eso es más de lo que pueden decir la mayoría de los vivos." }, signoff = "Sharlindra" },
  [52] = { greeting = "$N:", body = { "Sabrás disculpar la extensión de esta misiva. Entre los míos, una frase larga se toma o bien por señal de genio o bien por síntoma de enfermedad, y he optado por que se me tenga por genio.", "Mok'Morokk huyó como un niño asustado, y aunque desde entonces ha vuelto a hurtadillas para enfurruñarse entre nosotros, nadie en Murohelecho lo ha olvidado. El clan delibera ahora acerca de su sucesor. Los ogros deliberan a la manera de un desprendimiento: despacio, con estruendo y con heridos. Tharg serviría admirablemente, de ser más joven y estar menos quebrantado.", "Entretanto, la progenie de Onyxia permanece al sur, y yo permanezco como el único en Murohelecho a quien le inquieta el porqué. Tu labor entre los huevos nos ha procurado tiempo. Me propongo emplearlo con sabiduría, lo cual, en esta aldea, me convierte en una suerte de excéntrico." }, signoff = "Con mi más profunda consideración,\nDraz'Zilb" },
  [53] = { greeting = "$N:", body = { "Los eruditos tienen el colgante, y son lentos, como deben ser los eruditos. Yo mismo lo he mirado muchas veces. Los humanos ponen más de sí mismos en una joya que un orco en una espada.", "A lo que siempre vuelvo es al espía que se lo llevó. Vigiló Theramore durante semanas, solo, y se llevó el colgante en su última noche, y una criatura con forma de cangrejo lo mató de camino a casa. No terminó lo que había ido a hacer. Lo terminaste tú por él. Si los espíritus descansan por cosas así, el suyo debería descansar.", "Un clarividente aprende a esperar, y esperaré por el colgante todo lo que haga falta. Nuestro espía no tuvo ese lujo. Me alegra que te tuviera a ti." }, signoff = "Zor Árbol Solitario" },
  [54] = { greeting = "$N:", body = { "La astucia del raptor se disipó, como yo sabía que pasaría. Entonces Gor'mul y yo hablamos, como esperaba que pudiéramos.", "Escuchó. No sonrió, y yo no se lo pedí. Me preguntó si el joven Jefe de Guerra lleva de verdad la armadura de Orgrim y empuña su martillo, y le dije que sí. Después se quedó callado mucho rato. Luego me preguntó qué pueden hacer ahora los chamanes, y le mostré un poco, y no lo tiró al suelo.", "Eso no es un guerrero que ha vuelto. Pero es un guerrero que ha hecho una pregunta, y en todos los años que vagó solo, no creo que le preguntara nada a nadie.", "Le has hecho recorrer una parte del camino de vuelta, $N, y el resto es suyo." }, signoff = "Tor'gan\nSentencia" },
  [55] = { greeting = "$N:", body = { "Trol'kalar va de camino hacia Nimboya, en Grom'gol, envuelta en tres telas y llevada por dos de nuestros más rápidos, porque ninguno quería dejar que el otro la llevara solo.", "Ya sabes lo que significa el nombre, mon. Matatrols. Durante generaciones los hombres de Strom y de Arathor la empuñaron contra mi pueblo, y los abuelos de nuestros abuelos aprendieron a huir con solo verla. Ahora un trol la ha sostenido. Yo la he sostenido. Me temblaban las manos, y no me avergüenza decirlo.", "Hará falta donde luchan los nuestros, en los húmedos bosques de Zul'Gurub. Si recuerda para qué bando la forjaron, no sabría decirlo.", "Que esté en nuestras manos es obra tuya, $N." }, signoff = "Zengu\nSentencia" },
  [56] = { greeting = "$N:", body = { "El jefe me envió al otro lado del mar a buscar a su hijo menor, y lo llevaré a casa yo mismo. No como se fue. En una gema no más grande que mi puño, él mismo, libre de Zanzil por fin. Es más de lo que me atrevía a esperar cuando contaba cabezas de Cabellesangre junto al caldero.", "La Gran Serpiente lo libró del hacha de los cazadores de cabezas, y tú lo libraste del resto. Un alma retenida tanto tiempo por otro no despierta de golpe. Los Lanza Negra conocen la paciencia. Una vez cruzamos un mar entero, y volvimos por él.", "Nuestras canciones llevarán tu nombre, mon. La piedra se la dejo a los tallistas." }, signoff = "Nimboya\nCampamento Grom'gol" },
  [57] = { greeting = "$C:", body = { "Los fetiches son ceniza. Los quemé yo mismo a la orilla de la Charca de Lágrimas, con el viento a la espalda. Lo que hubiera dentro tardó mucho en dejar de humear.", "No dejo de pensar en ese exiliado de las Tierras del Interior. Miró la profecía de su sumo sacerdote y dijo lo que veía, y le escribieron la sentencia con sangre sobre piel seca y lo mandaron a vivir entre los Secacorteza. En cada ejército en que he servido había un hombre así. La mayoría tenían razón.", "Jammal'an sigue creyendo que su dios hará inmortales a los Atal'ai, y los dragones verdes vigilan el agua esperando el día en que lo intente." }, signoff = "Fel'zerul\nRocal" },
  [58] = { greeting = "$N:", body = { "El campamento resiste, y los Zarpaleña lo atacan menos, o eso dicen mis centinelas. Durante años los tuve por simples salvajes. Tu mapa me demostró lo contrario. Luchaban en dos frentes, y el del sur era el que los desgastaba. Algo los empujaba hacia el norte, y nosotros estábamos en medio.", "He estudiado las glándulas que le arrancaste a Aguijolatigador hasta poder dibujarlas de memoria. Lo que vive en las Galerías Retorcidas es organizado, paciente, y está más cerca de lo que me gustaría. Me corresponde asegurarme de que resistamos lo suficiente para aprender de ello.", "Por primera vez en mi vida siento lástima por los gnolls, y habría preferido seguir odiándolos." }, signoff = "Hadoken Zanco Veloz\nCampamento Mojache" },
  [59] = { greeting = "$N:", body = { "¡Ja! El recipiente está listo, mon, y los materiales que trajiste son mejores de lo que pedí. Madera astillada de antárbol, minerales de gigante, tendones de lechubestia, todos esos fragmentitos de metal. Clasifiqué cada pieza yo mismo, por el olor.", "Neeru dice que quedó satisfecho con la cabeza. Buen cliente, ese. No hace preguntas y paga en hierbas.", "Lo que el muisek y el recipiente hagan juntos es asunto mío, y de los espíritus. Pero te diré esto. Cuando metí el último fragmento, toda la choza se quedó en silencio, como se queda una selva cuando algo grande escucha.", "Tienes buenas manos para recolectar, $N, y un médico brujo siempre se fija en las manos." }, signoff = "Médico brujo Uzer'i\nCampamento Mojache" },
  [60] = { greeting = "$N:", body = { "Trabajaste duro en esa nieve. Cuatro clases de lechúcicos, cada una peor que la anterior, y acabaste con todas.", "Yo solo he visto Cuna del Invierno desde la boca de los túneles de los Fauces de Madera, blanca y callada. Tú has visto más que yo. Si nuestros caminos se cruzan, me gustaría oír cómo eran esas cuevas del sur.", "¿Qué clase de secreto vuelve locos a sus propios guardianes? Le he dado vueltas cada noche desde que volvieron los mensajeros. Lo que los elfos de la noche dejaron allí no lo dejaron para nosotros, y justo por eso tenemos que saberlo." }, signoff = "Trull Fallarruina\nPuesto del Veneno" },
  [61] = { greeting = "$N:", body = { "¿Me atrevo a decirlo otra vez? ¡Un triunfo! Se lo he dicho a todo el que en El Baluarte se quedara quieto lo suficiente.", "Me encanta un plan que funciona, y el nuestro funcionó tres veces. Me cuentan que la Cruzada encontró nuestro estandarte y se lanzó directa contra la Plaga, tal como esperábamos. Las torres se iluminaron en los rastreadores de mis sacerdotes como faros en un mapa. Y luego entraste en Andorhal y me trajiste un trozo de la filacteria de Araj, que es la única parte de la que ningún plan mío puede llevarse el mérito.", "La Plaga no va a renunciar a Andorhal por un exánime caído, y no te insultaré fingiendo lo contrario. Pero recordará quién lanzó a la Cruzada contra ella, quién marcó sus torres y quién entró después." }, signoff = "Sumo ejecutor Derrington\nEl Baluarte" },
  [62] = { greeting = "$N:", body = { "Sigo siendo Payson. Quiero que eso quede claro antes que nada. Tomé el nombre después de despertar a esta gloriosa no-muerte, y un paquete de una muerta no me hace cambiar de opinión.", "Te llamé buitre. Resultó que no lo eras, y descubro que haberme equivocado me molesta menos de lo que esperaba.", "Pero me quedé con lo que ella mandó. Con todo. Está en una caja debajo de las cajas de cucarachas, donde a nadie se le ocurrirá mirar, que es más o menos la idea." }, signoff = "Jeremiah Payson\nVendedor de cucarachas" },
  [63] = { greeting = "$N:", body = { "¡Sigo siendo el decimoctavo piloto! Lo sé. Estoy tan sorprendido como tú.", "El propulsor se disparó exactamente como dijo Shreev, es decir, todo de golpe. ¿El récord del circuito? Hecho añicos. También dos cajas y casi todas mis cejas. Las cejas están volviendo a crecer.", "Quería ver a los gnomos mirándome. No pude. Demasiado rápido. Ese es el problema de ir a tope: te pierdes el paisaje.", "Pozík ya está ajustando el nuevo regulador y murmurando algo sobre la seguridad.", "Gracias por tantas carreras de aquí para allá, $N. Yo estaba ocupado yendo rápido." }, signoff = "Razzeric\nEl Desierto de Sal" },
  [64] = { greeting = "$N:", body = { "Una nota breve, porque estoy en mitad de algo. Siempre estoy en mitad de algo.", "Los brazales de vínculo de roca han sido de un valor incalculable. Dos de ellos, al menos. Servo ha extraviado los otros tres, que es justo la razón por la que te pedí cinco, lo cual demuestra bastante bien el método.", "Los grilletes avanzan. Cuando estén terminados, un mago podrá vincular elementales de una fuerza que nadie ha vinculado antes, siempre que el coeficiente se comporte, y lo hará, ahora que he tenido en cuenta la arena.", "Lucien me dice que te hizo algo con las piedras que te sobraron. Lo habría hecho yo mismo, por supuesto, de habérseme ocurrido, cosa que no pasó, porque estaba pensando en los grilletes." }, signoff = "Con gratitud, y con prisa,\nLotwil Veriatus" },
  [65] = { greeting = "$N:", body = { "La tierra tiene tu nombre en la boca ahora. Es un buen nombre.", "Derribaste al khan Hratha. Derribaste al khan Jehn. Los Magram ya están débiles. Todavía oigo rugir sus tripas cuando sopla bien el viento. Me río cada vez.", "El cristal rojo descansa cálido en mis manos por la noche. Mi magia es fuerte ahora, más fuerte de lo que ningún khan creyó. Confiaban en su fuerza. No escuchaban a la tierra. La tierra recuerda a quien no escuchó.", "Tu nombre ya se pronuncia junto a nuestros fuegos. La tierra lo conoce, y yo estaré escuchando." }, signoff = "Uthek la Sabia" },
  [66] = { greeting = "$N:", body = { "Entre amigos, entonces.", "El último lote salió hacia el desierto, y me cuentan que los equipos de boxes estuvieron muy callados un par de días. Mientras tanto, bastante gente en Bahía del Botín parece deberme una copa, y he dejado de pagarme las mías.", "La mezcla de Zanzil le hace cosas raras a la levadura. A la gente también, pero la levadura es mi negocio, y yo en tu lugar lo dejaría así.", "Esto es lo que me gusta de ti. Llevaste un plan siniestro de Bahía del Botín al desierto y de vuelta, y ni una sola vez preguntaste para qué era. En su momento te pagué un poco más por eso. Esta carta no es un pago. Considérala un cumplido, de alguien que no los regala." }, signoff = "Loquillo Pinchabujas\nBahía del Botín" },
  [67] = { greeting = "$N:", body = { "¡Millones! Bueno. Miles, casi. Bueno, un número muy alentador de cientos, ¡y subiendo!", "El fabuloso Elixir de Tragonublo se vende mejor que cualquier cosa en Gadgetzan que no sea agua. Los clientes repiten, y esa es la señal de un producto de calidad. Algunos vuelven un poco más pequeños, o un poco más huesudos, o bajando flotando desde algún sitio, pero vuelven, y eso es lo que cuenta.", "Roxio va diciendo por ahí que le debo una. Qué mujer tan graciosa. Lo del polvo fue idea suya, de acuerdo, pero el genio estaba en remover.", "Estuviste allí desde el principio, $N, cuando sabía a glándula de rocío por dentro, y me acordaré de ello cuando sea famoso." }, signoff = "Marin Tragonublo\nGadgetzan" },
  [68] = { greeting = "$N:", body = { "La memoria me va volviendo a trozos. Un olor a sal. Un campo amplio junto al que creo que crecí. Una canción que alguien tarareaba mientras afilaba espadas. Nada en orden, y nada muy útil, pero todo mío.", "La Llama Dorada vuelve a mi hogar, donde podrán protegerla. Ahora recuerdo el camino. Eso es nuevo.", "Una vez te di un consejo: es peligroso ir solo. Habría hecho bien en seguirlo yo mismo.", "Sin ti, todavía estaría vagando por este cráter preguntando a desconocidos mi propio nombre." }, signoff = "Linken\nRefugio de Marshal" },
  [69] = { greeting = "$N:", body = { "Te estaba mirando, ¿sabes? Cuando el último brasero se apagó en la Guarida Sombría, mis hechizos pudieron volver a ver, y lo primero que me mostraron fuiste tú, en pie entre el humo. He escrutado muchísimas cosas en mi vida. No creo haberme alegrado nunca tanto de ver una.", "Islen me mandó saludos junto con el agua, y una advertencia a la que no dejo de dar vueltas: que lo que estoy afrontando es más grande de lo que sé, y que lo descubriré bastante pronto. Rara vez se equivoca. Al Consejo de la Sombra le golpearon la cabeza en Jaedenar, pero una serpiente así tiene más de una.", "Frondavil sigue enfermo, y lo seguirá mucho tiempo. Pero está un poco menos enfermo en un rincón oscuro, y la Madre Tierra lo ve, incluso donde nadie más lo ve." }, signoff = "Que la Madre Tierra te guarde,\nGreta Pezuñamusgo\nSantuario Esmeralda" },
  [70] = { greeting = "$N:", body = { "Desde que los conozco, mis amigos siempre han sido los listos. Legacki, Roxio y su cocina, Quixxil y lo que sea que haga Quixxil. Las mías eran las ideas de las que se reían, así que me las guardaba en el bolsillo.", "¡Se acabó! El yeti ha vuelto a casa, un poco chamuscado de una oreja, y cada vez que lo miro pienso: eso lo hice yo. Un yeti entero. A partir de un dibujo.", "Por cierto, todos me contestaron. No te diré lo que escribieron, ya que estuviste presente en casi todo. Pero dos de ellos me preguntaron cómo funciona, y esa es la parte que no dejo de releer.", "Llevaste un yeti mecánico por medio mundo por mí, $N. Nadie había hecho nunca algo tan disparatado en mi favor. Gracias." }, signoff = "Umi Risitas\nVista Eterna" },
  [71] = { greeting = "$N:", body = { "No he dormido bien desde que me trajiste ese libro. Los Anales de Villa Darrow. Mi hogar, escrito por alguien que no estaba allí, y luego continuado por algo que no entiendo.", "Dice que mi hermano Joseph se pasó al otro bando. Que fue corrompido, que traicionó a los defensores y que murieron por ello. Yo era uno de los defensores. Sobreviví. Hasta que lo leí, no sabía quién nos había traicionado.", "La calavera y la espada rota están guardadas bajo llave. No me gusta lo que siento cuando las toco, así que no las toco.", "Joseph tenía una hija. Hace años que no me permito pensar en ella." }, signoff = "Carlin Rutagrana\nCapilla de la Esperanza de la Luz" },
  [72] = { greeting = "$N:", body = { "Mi hijo te habló de su sueño, en el que yo por fin estaba a su lado en la Orden. Quería que terminara.", "Ahora sueño yo. El mismo sueño, creo. Estoy a su lado. Es un niño con un martillo de juguete, y luego es un hombre con su armadura, y luego ya no está. Me despierto antes del final. En eso, al menos, la Luz es misericordiosa.", "La Orden ha renacido. No quería asumirla así. Pero Taelan arrojó una vez su estandarte, y tú se lo devolviste, y no dejaré que caiga una segunda vez." }, signoff = "Tirión Vadín" },
  [73] = { greeting = "$N:", body = { "Me dicen que los tuyos, cuando están agradecidos, escriben. Marcas sobre una piel fina, plegada y llevada de mano en mano. Es una manera lenta de decir lo que una marea dice de una vez. Pero nos trajiste las manos de cuatro capitanes del fuego, así que probaré a tu manera.", "No entiendo cómo miden los tuyos la gratitud. Llevo mucho tiempo observando a los mortales, y los he visto darse las gracias por cosas muy pequeñas: una puerta sostenida, una copa llena. Lo que hiciste no fue algo pequeño. No sé lo grande que debe ser una carta entre mortales para algo tan grande.", "Esta tendrá que bastar. La guerra continúa. Pero tu nombre ha recorrido las cámaras de los Señores del Agua." }, signoff = "Duque Hydraxis" },
}
-- (the places Classic Era's client names otherwise, swapped in there)
ns.classicNames = { ["Campamento Grom'gol"] = "Campamento Grom'Gol", ["Galerías Retorcidas"] = "Entrañas Retorcidas" }
